pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any positive fundable amount (capped to stay realistic/wide)
        vm.assume(amount > 0 && amount <= 1e30);

        // Fund the contract directly with the fuzzed amount.
        vm.deal(address(c), amount);
        uint256 pre = address(c).balance;

        // The owner (the deployer, i.e. this test contract) drains the contract.
        c.withdrawAll();

        // General rule: a successful owner withdrawAll must strictly reduce the
        // contract's balance (it pays out to the owner). The mutant's empty
        // withdrawAll leaves the balance unchanged, breaking the rule for every
        // amount > 0 the fuzzer picks.
        assertTrue(address(c).balance < pre);
    }
}

