pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 2, 1e18);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok); // warm-up setup step, succeeds via payable fallback
        vm.prank(actor);
        c.withdrawAll();
        // Rule: after withdrawAll, the caller has been paid the ENTIRE contract
        // balance, i.e. exactly the amount they deposited (no dust left in C).
        assertTrue(address(actor).balance == amount);
    }
}

