pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        // Fund the contract WITHOUT triggering the fallback, so depositsCount stays 0
        // while the real (reference) withdrawAll still drains the whole balance.
        vm.deal(address(c), amount);
        vm.deal(address(this), 0);
        vm.prank(address(this));
        c.withdrawAll();
        // Reference: withdrew address(this).balance == amount, so c holds nothing.
        // Mutant: withdrew depositsCount == 0, so c still holds `amount`.
        assertTrue(address(c).balance == 0);
    }
}

