pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 value, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);
        value = bound(value, 1, amount - 1); // strictly partial withdrawal

        vm.deal(address(c), amount);
        vm.deal(actor, 1);

        vm.prank(actor);
        c.withdraw(value);

        assertTrue(address(c).balance == amount - value);
    }
}

