pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: owner requests a partial withdrawal, strictly less
        // than the contract balance, so a correct partial withdrawal must leave
        // funds behind
        amount = bound(amount, 1, type(uint256).max - 2);
        vm.deal(address(c), amount + 1);

        vm.prank(address(this)); // owner is the deployer of c
        c.withdraw(amount);

        assertTrue(address(c).balance > 0);
    }
}

